(function () {
'use strict';
var Utils = window.Utils;
var HttpApi = window.HttpApi;
var Merchant = window.Merchant;
var Upload = window.MerchantUpload;
if (!Merchant) return;
if (!Merchant.requireLogin()) return;
var EDIT_KEY = 'merchant_store_editing';
var storeId = '';
var submitting = false;
var uploading = false;
function $(id) { return document.getElementById(id); }
function clean(value) { return String(value == null ? '' : value).trim(); }
function hasCoord() {
var la = Number($('me-latitude').value);
var ln = Number($('me-longitude').value);
return $('me-latitude').value !== '' && $('me-longitude').value !== '' &&
isFinite(la) && isFinite(ln) && (la !== 0 || ln !== 0);
}
function syncGeo() {
var ok = hasCoord();
var tip = $('me-geo-tip');
tip.className = ok ? 'merchant-geo-ok' : 'merchant-geo-none';
tip.textContent = ok ? '已填坐标，保存后可被「就近门店」检索' : '填写经纬度后可被「就近门店」检索';
}
function syncLogo() {
var url = Utils.firstImage(clean($('me-logo').value));
var img = $('me-logo-img');
var plus = $('me-logo-plus');
var clear = $('me-logo-clear');
if (url) {
img.src = url;
img.hidden = false;
plus.hidden = true;
} else {
img.removeAttribute('src');
img.hidden = true;
plus.hidden = false;
}
clear.hidden = !url;
}
function syncDesc() {
var len = ($('me-describe').value || '').length;
$('me-counter').textContent = len + '/300';
}
function syncSubmit() {
var btn = $('me-submit');
btn.disabled = submitting;
btn.textContent = submitting ? '保存中…' : (storeId ? '保存修改' : '创建店铺');
}
function fillFromStorage() {
var row = null;
try {
row = JSON.parse(localStorage.getItem(EDIT_KEY) || 'null');
localStorage.removeItem(EDIT_KEY);
} catch (e) { row = null; }
if (!row || String(row._id || row.id) !== storeId) return;
$('me-name').value = row.name || '';
$('me-city').value = row.city || '';
$('me-category').value = row.category || '';
$('me-phone').value = row.phone || '';
var position = row.position;
if (typeof position === 'string') {
$('me-position').value = position;
} else if (position && typeof position === 'object') {
$('me-position').value = position.address || '';
if (position.latitude != null) $('me-latitude').value = position.latitude;
if (position.longitude != null) $('me-longitude').value = position.longitude;
}
$('me-logo').value = Utils.firstImage(row.logo) || '';
$('me-describe').value = row.describe || '';
}
function uploadLogo() {
if (uploading || !Upload) return;
uploading = true;
$('me-logo-busy').hidden = false;
Upload.uploadImage().then(function (url) {
uploading = false;
$('me-logo-busy').hidden = true;
$('me-logo').value = url;
syncLogo();
Merchant.toast('Logo 已上传');
}).catch(function (err) {
uploading = false;
$('me-logo-busy').hidden = true;
var msg = (err && err.message) || '';
if (/cancel/i.test(msg)) return;
Merchant.toast(msg || '上传失败');
});
}
function submit(e) {
e.preventDefault();
if (submitting) return;
var name = clean($('me-name').value);
if (!name) {
Merchant.toast('请填写店铺名称');
return;
}
var address = clean($('me-position').value);
var position = address;
if (hasCoord()) {
position = {
address: address,
latitude: Number($('me-latitude').value),
longitude: Number($('me-longitude').value)
};
}
var payload = {
name: name,
city: clean($('me-city').value),
category: clean($('me-category').value),
phone: clean($('me-phone').value),
position: position,
logo: clean($('me-logo').value),
describe: clean($('me-describe').value)
};
if (storeId) payload.id = storeId;
submitting = true;
syncSubmit();
HttpApi.merchant.storeSave(payload).then(function (res) {
submitting = false;
syncSubmit();
if (Merchant.authExpired(res)) return;
if (res && res.code === 0) {
Merchant.toast(storeId ? '已保存' : '店铺已创建');
Utils.track(storeId ? 'merchant_store_update' : 'merchant_store_create', { id: storeId });
setTimeout(function () {
window.location.href = '/merchant/stores.html';
}, 500);
} else {
Merchant.toast((res && res.msg) || '保存失败，请稍后重试');
}
}).catch(function () {
submitting = false;
syncSubmit();
Merchant.toast('网络异常，请稍后重试');
});
}
function init() {
if (!HttpApi) return;
var params = new URLSearchParams(window.location.search);
storeId = params.get('id') || '';
if (storeId) fillFromStorage();
$('me-title').textContent = storeId ? '编辑店铺' : '新建店铺';
$('me-form').addEventListener('submit', submit);
$('me-logo-box').addEventListener('click', uploadLogo);
$('me-logo').addEventListener('input', syncLogo);
$('me-logo-clear').addEventListener('click', function () {
$('me-logo').value = '';
syncLogo();
});
$('me-describe').addEventListener('input', syncDesc);
$('me-latitude').addEventListener('input', syncGeo);
$('me-longitude').addEventListener('input', syncGeo);
syncLogo();
syncDesc();
syncGeo();
syncSubmit();
Utils.track('merchant_store_edit_visit', { id: storeId || 'new' });
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
